(function () {
  var p = (pol && pol.data) ? pol.data : {};
  var policyId = String((trg && trg.policy_id) || '');
  if (!policyId) { throw new Error('policy-void: the timer payload carries no policy_id'); }
  return {
    policy_id: policyId,
    broker_id: String(p.broker_id || ''),
    invoice_filter: JSON.stringify({ conditions: [{ field: 'policy_id', keyword: policyId }] }),
    broker_filter: JSON.stringify({ conditions: [{ field: 'broker_id', keyword: String(p.broker_id || '') || '__no_broker__' }] }),
    now: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z')
  };
})();

(function () {
  function iso(d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); }
  var p = (pol && pol.data) ? pol.data : {};
  var rows = (inv && inv.data && inv.data.results) ? inv.data.results : [];
  var seen = {}, list = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (!r || !r.id || seen[r.id]) continue;
    seen[r.id] = 1; list.push(r);
  }
  var open = [];
  for (var j = 0; j < list.length; j++) {
    var d = list[j].data || {};
    if (d.payment_status === 'unpaid' || d.payment_status === 'overdue') open.push(list[j]);
  }
  open.sort(function (a, b) {
    return String((a.data || {}).due_date || '') < String((b.data || {}).due_date || '') ? -1 : 1;
  });
  var chosen = open.length ? open[0] : null;
  var cd = chosen ? (chosen.data || {}) : {};

  // ---- honouring the PER-POLICY void_after_days -------------------------
  // The timer was booked at bind from the void_after_days in force then. A term
  // extension or an override can move void_after_days afterwards without
  // rescheduling, so the fire time is a hint and void_due_date is the authority.
  // Where void_due_date is absent it is recomputed from bind_date so the
  // per-policy number is still honoured rather than a global 61 being assumed.
  var days = Number(p.void_after_days);
  if (!(days > 0)) days = Number(defaultDays) || 61;
  var bind = p.bind_date ? new Date(p.bind_date) : null;
  var stored = p.void_due_date ? new Date(p.void_due_date) : null;
  var derived = (bind && !isNaN(bind.getTime())) ? new Date(bind.getTime() + days * 86400000) : null;
  var due = (stored && !isNaN(stored.getTime())) ? stored : derived;
  var nowMs = Date.now();
  var dueMs = due ? due.getTime() : NaN;

  var brows = (brk && brk.data && brk.data.results) ? brk.data.results : [];
  var to = '', toName = '';
  for (var k = 0; k < brows.length; k++) {
    var bd = brows[k].data || {};
    if (bd.primary_contact_email) { to = String(bd.primary_contact_email); toName = String(bd.brokerage_name || bd.primary_contact_name || ''); break; }
  }
  if (!to) { to = String(fallback || ''); toName = 'Antipodean Operations'; }

  var status = String(p.policy_status || '');
  var noticeSent = String(p.voidance_notice_state || '') === 'sent';
  var reasons = [];
  if (!(status === 'ACTIVE' || status === 'OVERDUE')) reasons.push('policy_status_is_' + (status || 'absent'));
  if (!chosen) reasons.push('no_unpaid_or_overdue_invoice');
  // Idempotency is on us: the status is written first and the notice second,
  // and the send is gated on the absence of the stamp (plan 5.3 rule 3).
  if (noticeSent) reasons.push('voidance_notice_already_sent');
  if (isNaN(dueMs)) reasons.push('no_void_due_date_and_no_bind_date');

  var action = 'skip';
  if (reasons.length === 0) {
    // A 60s tolerance stops a timer that fires a few milliseconds early from
    // booking a pointless reschedule.
    action = (nowMs + 60000 >= dueMs) ? 'void' : 'reschedule';
    if (action === 'reschedule') reasons.push('void_due_date_moved_out_to_' + iso(due));
  }

  return {
    action: action,
    is_void: action === 'void',
    is_reschedule: action === 'reschedule',
    notes: reasons,
    policy_id: String((trg && trg.policy_id) || ''),
    policy_number: String(p.policy_number || ''),
    policy_status_before: status,
    inception_date: String(p.inception_date || ''),
    void_after_days: days,
    void_due_date: due ? iso(due) : '',
    void_due_date_source: (stored && !isNaN(stored.getTime())) ? 'policy.void_due_date' : 'derived_from_bind_date',
    invoice_id: chosen ? String(chosen.id) : '',
    invoice_number: String(cd.invoice_number || ''),
    amount_due_text: (Number(cd.amount_due || 0)).toFixed(2),
    // The timer name is composed from the frozen registry in config.static,
    // never from a literal this flow wrote itself (artefact 5, ASSERT-1c).
    reschedule_name: String(concern) + ':' + String((trg && trg.policy_id) || ''),
    // unschedule-flow accepts only the STORED topic. It cannot fail: a
    // nonexistent topic returns 200, which is why the stored fields are cleared
    // in the same write that records the cancellation (artefact 5, ASSERT-2c).
    renewal_generate_topic: String(p.renewal_generate_timer_topic || '') || 'antipodean.nothing-to-cancel',
    renewal_dispatch_topic: String(p.renewal_dispatch_timer_topic || '') || 'antipodean.nothing-to-cancel',
    had_renewal_generate_topic: !!p.renewal_generate_timer_topic,
    had_renewal_dispatch_topic: !!p.renewal_dispatch_timer_topic,
    notice_to: to,
    notice_to_name: toName,
    voided_at: iso(new Date()),
    assessed_at: iso(new Date())
  };
})();

(function () {
  // ASSERT-2b: a re-schedule re-stamps the returned topic as its next act. The
  // returned Topic is the only string unschedule-flow accepts; deriving it
  // locally is a repair tool for flow 13, never the contract.
  function topicOf(resp) {
    if (!resp || typeof resp !== 'object') return '';
    if (typeof resp.topic === 'string') return resp.topic;
    if (resp.data && typeof resp.data.topic === 'string') return resp.data.topic;
    if (resp.results && resp.results.length && resp.results[0].topic) return resp.results[0].topic;
    return '';
  }
  var t = topicOf(sched);
  if (!t) { throw new Error('policy-void: the reschedule returned no topic — the void timer would be uncancellable'); }
  return { policy_void_timer_topic: t, rescheduled_for: String(when || '') };
})();
